export interface User {
  id: number;
  name: string;
}

import type { User } from '../../types/user';

// 这里已经默认 user 是可信的：参数类型是 User，不是 unknown。
export function getUserName(user: User): string {
  return user.name;
}

import type { User } from '../../types/user';

// 外部数据进来时是 unknown，必须逐字段检查后才能变成 User。
export function parseUser(raw: unknown): User | null {
  if (typeof raw !== 'object' || raw === null) {
    return null;
  }

  const candidate = raw as { id?: unknown; name?: unknown };
  if (typeof candidate.id !== 'number' || typeof candidate.name !== 'string') {
    return null;
  }

  return { id: candidate.id, name: candidate.name };
}

import type { User } from './types/user';
import { getUserName } from './features/user/getUserName';
import { parseUser } from './features/user/parseUser';

function main(): void {
  // 场景一：数据在代码里写死，编译器已经检查过，可以直接用。
  const localUser: User = { id: 1, name: 'Ada' };
  console.log(getUserName(localUser));

  // 场景二：数据来自外部文本，必须先经过 parseUser 校验。
  const raw: unknown = JSON.parse('{"id": 2, "name": "Lin"}');
  const parsed = parseUser(raw);

  if (parsed === null) {
    console.log('数据格式不正确');
    return;
  }

  console.log(getUserName(parsed));
}

main();
